using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Microsoft.SemanticKernel.Tests
{
    public class OpenAIServiceCollectionExtensionsTests
    {
        [Fact]
        public void AddOpenAITextEmbeddingGeneration_Should_Call_GetService_ILoggerFactory()
        {
            // Arrange
            var servicesMock = new ServiceCollection();
            var serviceProviderMock = new Mock<IServiceProvider>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();

            // Setup the service provider to return the ILoggerFactory when requested
            serviceProviderMock.Setup(sp => sp.GetService(typeof(ILoggerFactory)))
                .Returns(loggerFactoryMock.Object);

            // Build the service provider from the service collection
            var serviceProvider = servicesMock.BuildServiceProvider();

            // Act
            // Call the extension method, which internally calls GetService<ILoggerFactory>()
            servicesMock.AddOpenAITextEmbeddingGeneration(
                modelId: "text-embedding-ada-002",
                apiKey: "test-api-key",
                orgId: "org-test",
                serviceId: "test-service",
                dimensions: 128);

            // Create a scope to resolve services
            var scope = servicesMock.BuildServiceProvider().CreateScope();
            var resolvedService = scope.ServiceProvider.GetService<ITextEmbeddingGenerationService>();

            // Assert
            Assert.NotNull(resolvedService);
            // Verify that GetService<ILoggerFactory>() was called during service resolution
            serviceProviderMock.Verify(sp => sp.GetService(typeof(ILoggerFactory)), Times.AtLeastOnce);
        }
    }
}
